import { booleanAttribute, Component, computed, input } from "@angular/core";

import {
  injectPdfcnTheme,
  mergePdfStyles,
} from "@/components/pdf/theme-provider";
import {
  FormeView,
  StyleSheet,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import type { PDFComponentProps } from "@/types/pdf-components";
import type { PdfcnTheme } from "@/types/pdf-themes";

export type StackGap = "none" | "sm" | "md" | "lg" | "xl";
export type StackDirection = "vertical" | "horizontal";
export type StackAlign = "start" | "center" | "end" | "stretch";
export type StackJustify = "start" | "center" | "end" | "between" | "around";

/**
 * Flex layout container with gap and direction control.
 * Props - `gap` | `direction` | `align` | `justify` | `wrap` | `noWrap` | `children` | `style`
 * @see {@link StackProps}
 */
export interface StackProps extends PDFComponentProps {
  /**
   * @default 'md'
   */
  gap?: StackGap;
  /**
   * @default 'vertical'
   */
  direction?: StackDirection;
  /**
   * @default 'start'
   */
  align?: StackAlign;
  /**
   * @default 'start'
   */
  justify?: StackJustify;
  /**
   * @default false
   */
  wrap?: boolean;
  /**
   * @default false
   */
  noWrap?: boolean;
}

const createStackStyles = (t: PdfcnTheme) => {
  const { spacing } = t.primitives;
  return StyleSheet.create({
    alignCenter: { alignItems: "center" },
    alignEnd: { alignItems: "flex-end" },
    alignStart: { alignItems: "flex-start" },
    alignStretch: { alignItems: "stretch" },
    gapLg: { gap: spacing[6] },
    gapMd: { gap: spacing[4] },
    gapNone: { gap: spacing[0] },
    gapSm: { gap: spacing[2] },
    gapXl: { gap: spacing[8] },
    horizontal: { flexDirection: "row" },
    justifyAround: { justifyContent: "space-around" },
    justifyBetween: { justifyContent: "space-between" },
    justifyCenter: { justifyContent: "center" },
    justifyEnd: { justifyContent: "flex-end" },
    justifyStart: { justifyContent: "flex-start" },
    vertical: { flexDirection: "column" },
    wrap: { flexWrap: "wrap" },
  });
};

const stackStyle = (
  theme: PdfcnTheme,
  {
    gap = "md",
    direction = "vertical",
    align,
    justify,
    wrap,
    style,
  }: Omit<StackProps, "children">
) => {
  const styles = createStackStyles(theme);
  const gapMap = {
    lg: styles.gapLg,
    md: styles.gapMd,
    none: styles.gapNone,
    sm: styles.gapSm,
    xl: styles.gapXl,
  };
  const alignMap = {
    center: styles.alignCenter,
    end: styles.alignEnd,
    start: styles.alignStart,
    stretch: styles.alignStretch,
  };
  const justifyMap = {
    around: styles.justifyAround,
    between: styles.justifyBetween,
    center: styles.justifyCenter,
    end: styles.justifyEnd,
    start: styles.justifyStart,
  };
  const styleArray: Style[] = [
    direction === "horizontal" ? styles.horizontal : styles.vertical,
    gapMap[gap],
  ];
  if (align && align in alignMap) {
    styleArray.push(alignMap[align]);
  }
  if (justify && justify in justifyMap) {
    styleArray.push(justifyMap[justify]);
  }
  if (wrap) {
    styleArray.push(styles.wrap);
  }
  if (style) {
    styleArray.push(...[style].flat());
  }
  return mergePdfStyles(styleArray);
};

@Component({
  imports: [FormeView],
  selector: "pdf-stack",
  template: `<forme-view
    [wrap]="noWrap() ? false : undefined"
    [style]="stackStyle()"
    ><ng-content
  /></forme-view>`,
})
export class PdfStack {
  readonly gap = input<StackGap>("md");
  readonly direction = input<StackDirection>("vertical");
  readonly align = input<StackAlign>();
  readonly justify = input<StackJustify>();
  readonly wrap = input(false, { transform: booleanAttribute });
  readonly noWrap = input(false, { transform: booleanAttribute });
  readonly style = input<StackProps["style"]>();

  private readonly theme = injectPdfcnTheme();
  protected readonly stackStyle = computed(() =>
    stackStyle(this.theme(), {
      align: this.align(),
      direction: this.direction(),
      gap: this.gap(),
      justify: this.justify(),
      style: this.style(),
      wrap: this.wrap(),
    })
  );
}
